    @Test
    void acceptsACompanyOrAForeignGuestInsteadOfTheCpf() throws Exception {
        String company = RESERVATION_JSON.replace("\"guestCpf\": \"111.222.333-44\"",
                "\"companyCnpj\": \"12.345.678/0001-90\", \"companyName\": \"Tecnosul Ltda\"");
        JsonNode invoiced = json.readTree(post("/reservations", company).body());
        assertEquals("12.345.678/0001-90", invoiced.get("companyCnpj").asText());
        assertTrue(invoiced.get("guestCpf").isNull());
        assertTrue(invoiced.get("guestPassport").isNull());

        String foreigner = company.replace("\"companyCnpj\": \"12.345.678/0001-90\", \"companyName\": \"Tecnosul Ltda\"",
                "\"guestPassport\": \"X1234567\", \"guestCountry\": \"Chile\"")
                .replace("2027-07-1", "2027-08-1");
        HttpResponse<String> created = post("/reservations", foreigner);
        assertEquals(201, created.statusCode());
        long id = json.readTree(created.body()).get("id").asLong();
        post("/reservations/" + id + "/confirmation", "");

        JsonNode document = json.readTree(get("/reservations/" + id + "/document").body());
        assertEquals("Booking receipt", document.get("title").asText());
        assertEquals("X1234567", document.get("guestPassport").asText());
        assertEquals("Chile", document.get("guestCountry").asText());
        assertTrue(document.get("guestCpf").isNull());
        assertTrue(document.get("companyCnpj").isNull());
        assertTrue(document.get("text").asText().startsWith("Booking receipt no. " + id + "\n"));
    }

    @Test
    void needsExactlyOneWayToIdentifyTheGuest() throws Exception {
        String cpf = "\"guestCpf\": \"111.222.333-44\"";
        for (String identification : new String[] {
            "\"guestName\": \"Carla Dias\"",
            cpf + ", \"companyCnpj\": \"12\", \"companyName\": \"Tecnosul\"",
            cpf + ", \"guestPassport\": \"X1\", \"guestCountry\": \"Chile\"",
            "\"companyCnpj\": \"12\"",
            "\"guestPassport\": \"X1\"",
        }) {
            String body = RESERVATION_JSON.replace(cpf, identification);
            HttpResponse<String> response = post("/reservations", body);
            assertEquals(400, response.statusCode(), identification);
            assertEquals("INVALID_REQUEST", json.readTree(response.body()).get("error").asText());
        }
    }
}
